class VectorMemory:
    def __init__(self):
        self.index = None
        self.embedding_model = None
        try:
            self.pinecone_client = Pinecone(api_key=os.getenv('PINECONE_API_KEY'))
            self.embedding_model = SentenceTransformer('all-MiniLM-L6-v2')
            try:
                self.index = self.pinecone_client.Index('cognitive-memory')
                logger.info("Pinecone vector memory initialized successfully")
            except Exception as e:
                logger.warning(f"Pinecone index not found, attempting to create: {e}")
                pinecone_region = os.getenv('PINECONE_REGION', 'us-east-1')
                self.pinecone_client.create_index(
                    name='cognitive-memory',
                    dimension=384,
                    metric='cosine',
                    spec=ServerlessSpec(cloud='aws', region=pinecone_region)
                )
                time.sleep(60)
                self.index = self.pinecone_client.Index('cognitive-memory')
                logger.info("Pinecone index created successfully")
        except Exception as e:
            logger.warning(f"Pinecone initialization failed: {e} - Vector memory disabled")

    def store_insight(self, content: str, metadata: Dict):
        if not self.index or not self.embedding_model:
            logger.debug("Vector memory not available - skipping insight storage")
            return None
        try:
            vector_id = hashlib.sha256(f"{content}{time.time()}".encode()).hexdigest()
            embedding = self.embedding_model.encode(content).tolist()
            self.index.upsert(vectors=[{
                'id': vector_id,
                'values': embedding,
                'metadata': {
                    **metadata,
                    'content': content[:1000],
                    'timestamp': time.time()
                }
            }])
            return vector_id
        except Exception as e:
            logger.error(f"Failed to store insight: {e}")
            return None

    def recall_similar(self, query: str, top_k: int = 20) -> List[Dict]:
        if not self.index or not self.embedding_model:
            logger.debug("Vector memory not available - returning empty memories")
            return []
        try:
            query_embedding = self.embedding_model.encode(query).tolist()
            results = self.index.query(vector=query_embedding, top_k=top_k, include_metadata=True)
            recalled = []
            for match in results.matches:
                recalled.append({
                    'content': match.metadata.get('content', ''),
                    'score': match.score,
                    'metadata': match.metadata
                })
            return recalled
        except Exception as e:
            logger.error(f"Pinecone recall_similar failed: {e}")
            return []

class PlannerModule:
    def __init__(self, cerebras_client: Cerebras, xai_client: OpenAI):
        self.cerebras = cerebras_client
        self.xai = xai_client

    def create_research_plan(self, query: str, context: List[Dict]) -> Dict:
        context_text = "\n".join([f"- {item['content'][:500]}" for item in context[:10]])
        planning_prompt = f"""You are a strategic research planner. Create a comprehensive, adaptive research plan.

Query: {query}

Previous knowledge from memory:
{context_text}

Create a detailed research plan with:
1. Primary research objectives (3-5 specific goals)
2. Search strategies (multiple angles to explore)
3. Key questions to answer
4. Expected challenges and how to overcome them
5. Success criteria
6. Contingency plans if initial approaches fail

Return as JSON:
{{
  "objectives": ["obj1", "obj2", "obj3"],
  "search_strategies": [
    {{"strategy": "comprehensive analysis", "rationale": "thorough coverage", "priority": 5}}
  ],
  "key_questions": ["q1", "q2", "q3"],
  "challenges": [
    {{"challenge": "data scarcity", "mitigation": "multiple sources"}}
  ],
  "success_criteria": ["criterion1", "criterion2"],
  "contingencies": [
    {{"if": "insufficient data", "then": "expand search scope"}}
  ]
}}"""
        try:
            response = self.cerebras.chat.completions.create(
                model="qwen-3-235b-a22b-thinking-2507",
                messages=[{"role": "user", "content": planning_prompt}],
                max_tokens=64000,
                temperature=0.8
            )
            plan_text = response.choices[0].message.content
            try:
                plan = json.loads(plan_text)
            except Exception as e:
                logger.warning(f"Plan JSON parse failed: {e}")
                plan = {
                    "objectives": ["Comprehensive research on the query"],
                    "search_strategies": [{"strategy": "Multi-angle search", "rationale": "Coverage", "priority": 5}],
                    "key_questions": [query],
                    "challenges": [],
                    "success_criteria": ["Thorough report"],
                    "contingencies": []
                }
            return plan
        except Exception as e:
            return {
                "objectives": [query],
                "search_strategies": [{"strategy": "Comprehensive search", "rationale": "Default", "priority": 5}],
                "key_questions": [query],
                "challenges": [],
                "success_criteria": [],
                "contingencies": [],
                "error": str(e)
            }

    def replan(self, original_plan: Dict, execution_results: Dict, iteration: int) -> Dict:
        replan_prompt = f"""You are replanning research strategy based on execution results.

Original plan objectives: {json.dumps(original_plan.get('objectives', []))}
Execution iteration: {iteration}
Results summary: {json.dumps(execution_results, indent=2)[:5000]}

Analyze what's working and what's not. Create an updated plan that:
1. Doubles down on successful strategies
2. Abandons unproductive approaches
3. Explores new angles based on findings
4. Adjusts priorities based on results

Return updated plan as JSON with same structure as original."""
        try:
            response = self.xai.chat.completions.create(
                model="grok-4-fast",
                messages=[{"role": "user", "content": replan_prompt}],
                max_tokens=32768,
                temperature=0.7
            )
            updated_plan = json.loads(response.choices[0].message.content)
            return updated_plan
        except Exception as e:
            logger.warning(f"Replan failed: {e}")
            return original_plan

class CriticModule:
    def __init__(self, bedrock_client, cerebras_client: Cerebras):
        self.bedrock = bedrock_client
        self.cerebras = cerebras_client

    def critique_findings(self, findings: str, sources: List[Dict]) -> Dict:
        if not self.bedrock:
            logger.warning("Bedrock not available - skipping critique")
            return {
                "logical_issues": [],
                "missing_evidence": [],
                "biases": [],
                "contradictions": [],
                "unanswered_questions": [],
                "alternative_views": [],
                "source_quality_issues": [],
                "overall_confidence": 75,
                "recommendations": ["Critique skipped - AWS Bedrock not configured"]
            }
        sources_summary = "\n".join([f"[{i+1}] {s.get('title', 'Untitled')}: {s.get('url', '')}" for i, s in enumerate(sources[:30])])
        critique_prompt = f"""You are a critical analyst. Your job is to find flaws, biases, gaps, and logical errors.

Findings to critique:
{findings[:20000]}

Sources used:
{sources_summary}

Provide critical analysis:
1. Logical fallacies or weak reasoning
2. Missing evidence or unsupported claims
3. Potential biases in sources
4. Contradictions or inconsistencies
5. Important questions left unanswered
6. Alternative interpretations
7. Quality and credibility of sources

Return as JSON:
{{
  "logical_issues": ["issue1", "issue2"],
  "missing_evidence": ["gap1", "gap2"],
  "biases": ["bias1", "bias2"],
  "contradictions": ["contradiction1"],
  "unanswered_questions": ["q1", "q2"],
  "alternative_views": ["view1", "view2"],
  "source_quality_issues": ["issue1"],
  "overall_confidence": 0-100,
  "recommendations": ["rec1", "rec2"]
}}"""
        try:
            body = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 200000,
                "messages": [{"role": "user", "content": critique_prompt}],
                "temperature": 0.7
            })
            response = self.bedrock.invoke_model(
                modelId="anthropic.claude-sonnet-4-5-v2:0",
                body=body
            )
            response_body = json.loads(response['body'].read())
            critique_text = response_body['content'][0]['text']
            try:
                critique = json.loads(critique_text)
            except Exception as e:
                logger.warning(f"Critique JSON parse failed: {e}")
                critique = {
                    "logical_issues": [],
                    "missing_evidence": [],
                    "biases": [],
                    "contradictions": [],
                    "unanswered_questions": [],
                    "alternative_views": [],
                    "source_quality_issues": [],
                    "overall_confidence": 50,
                    "recommendations": []
                }
            return critique
        except Exception as e:
            logger.error(f"Critique failed: {e}")
            return {
                "error": str(e),
                "overall_confidence": 50,
                "recommendations": ["Manual review recommended"]
            }

    def defend_or_revise(self, findings: str, critique: Dict) -> Dict:
        defense_prompt = f"""You are defending or revising findings based on critical feedback.

Original findings:
{findings[:15000]}

Critical feedback:
{json.dumps(critique, indent=2)}

For each criticism:
1. Either defend the original finding with stronger evidence
2. Or revise the finding to address the criticism

Return as JSON:
{{
  "defended": [
    {{"criticism": "specific criticism", "defense": "defense argument", "evidence": "supporting evidence"}}
  ],
  "revised": [
