class MultiAgentCoordinator:
    def __init__(self, exa: Exa, cerebras: Cerebras, xai: OpenAI, bedrock):
        self.exa = exa
        self.cerebras = cerebras
        self.xai = xai
        self.bedrock = bedrock

    def librarian_agent(self, query: str, constraints: Dict) -> Dict:
        try:
            search_types = ['neural', 'keyword', 'auto']
            all_results = []
            for search_type in search_types:
                result = self.exa.search_and_contents(
                    query=query,
                    type=search_type,
                    num_results=100,
                    text=True,
                    highlights=True,
                    livecrawl="preferred",
                    **constraints
                )
                all_results.extend([{
                    'url': r.url,
                    'title': getattr(r, 'title', ''),
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'search_type': search_type
                } for r in result.results])
            return {'agent': 'librarian', 'results': all_results, 'count': len(all_results)}
        except Exception as e:
            return {'agent': 'librarian', 'results': [], 'error': str(e)}

    def data_analyst_agent(self, sources: List[Dict]) -> Dict:
        analysis_prompt = f"""You are a data analyst. Extract quantitative insights, statistics, trends from these sources.

Sources:
{json.dumps([{'title': s.get('title', ''), 'text': s.get('text', '')[:20000]} for s in sources[:100]], indent=2)[:30000]}

Return structured analysis as JSON:
{{
  "statistics": [
    {{"metric": "population growth", "value": "2.5% annually", "source": "World Bank", "confidence": 85}}
  ],
  "trends": [
    {{"trend": "increasing adoption", "direction": "up", "evidence": "25% year-over-year growth"}}
  ],
  "correlations": [
    {{"factor1": "investment", "factor2": "innovation", "relationship": "positive correlation"}}
  ],
  "data_quality": {{
    "completeness": 80,
    "reliability": 75,
    "recency": "current"
  }}
}}"""
        try:
            response = self.cerebras.chat.completions.create(
                model="gpt-oss-120b",
                messages=[{"role": "user", "content": analysis_prompt}],
                max_tokens=65000,
                temperature=0.5
            )
            analysis = json.loads(response.choices[0].message.content)
            return {'agent': 'data_analyst', 'analysis': analysis}
        except Exception as e:
            return {'agent': 'data_analyst', 'error': str(e)}

    def synthesis_agent(self, all_inputs: Dict) -> str:
        if not self.bedrock:
            logger.warning("Bedrock not available - using fallback synthesis")
            return f"Multi-agent research synthesis:\n\nSources analyzed: {all_inputs.get('sources', [])[:5]}\n\nNote: Full synthesis unavailable - AWS Bedrock not configured."
        synthesis_prompt = f"""You are a synthesis specialist. Integrate all information into coherent insights.

Inputs from multiple agents:
{json.dumps(all_inputs, indent=2)[:40000]}

Create a synthesized narrative that:
1. Integrates all perspectives
2. Resolves contradictions
3. Highlights consensus and disagreements
4. Provides nuanced conclusions

Write a comprehensive synthesis (5000+ words)."""
        try:
            body = json.dumps({
                "anthropic_version": "bedrock-2023-05-31",
                "max_tokens": 200000,
                "messages": [{"role": "user", "content": synthesis_prompt}],
                "temperature": 0.6
            })
            response = self.bedrock.invoke_model(
                modelId="anthropic.claude-sonnet-4-5-v2:0",
                body=body
            )
            response_body = json.loads(response['body'].read())
            synthesis = response_body['content'][0]['text']
            return synthesis
        except Exception as e:
            logger.error(f"Synthesis error: {e}")
            return f"Synthesis error: {str(e)}"

    def coordinate_research(self, query: str, plan: Dict) -> Dict:
        librarian_results = []
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = []
            for strategy in plan.get('search_strategies', [])[:5]:
                search_query = strategy.get('strategy', query)
                futures.append(executor.submit(self.librarian_agent, search_query, {}))
            for future in as_completed(futures):
                result = future.result()
                librarian_results.extend(result.get('results', []))
        all_sources = []
        seen_urls = set()
        for item in librarian_results:
            if item['url'] not in seen_urls:
                seen_urls.add(item['url'])
                all_sources.append(item)
        analyst_result = self.data_analyst_agent(all_sources[:100])
        synthesis = self.synthesis_agent({
            'query': query,
            'plan': plan,
            'sources': all_sources[:200],
            'analyst_insights': analyst_result
        })
        return {
            'sources': all_sources,
            'analysis': analyst_result,
            'synthesis': synthesis,
            'metadata': {
                'total_sources': len(all_sources),
                'unique_urls': len(seen_urls)
            }
        }

class CognitiveDeepSearchAgent:
    def __init__(self):
        logger.info("Initializing CognitiveDeepSearchAgent...")
        self.exa = Exa(api_key=os.getenv('EXA_API_KEY'))
        self.cerebras = Cerebras(api_key=os.getenv('CEREBRAS_API_KEY'))
        self.xai_client = OpenAI(base_url="", api_key=os.getenv('XAI_API_KEY'))
        self.bedrock = None
        if os.getenv('AWS_ACCESS_KEY_ID') and os.getenv('AWS_SECRET_ACCESS_KEY'):
            try:
                aws_region = os.getenv('AWS_REGION', 'us-east-1')
                self.bedrock = boto3.client(
                    'bedrock-runtime',
                    region_name=aws_region,
                    aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
                    aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY')
                )
                logger.info("AWS Bedrock initialized successfully")
            except Exception as e:
                logger.warning(f"AWS Bedrock initialization failed: {e}")
        else:
            logger.warning("AWS credentials not found - Bedrock features will be disabled")
        self.redis_clients = []
        upstash_url = os.getenv('UPSTASH_REDIS_REST_URL')
        if upstash_url and upstash_url.startswith(('redis://', 'rediss://')):
            try:
                self.redis_clients.append(redis.from_url(upstash_url))
                logger.info("Upstash Redis connected")
            except Exception as e:
                logger.warning(f"Upstash Redis connection failed: {e}")
        dragonfly_url = os.getenv('DRAGONFLY_REDIS_URL')
        if dragonfly_url:
            try:
                self.redis_clients.append(redis.from_url(dragonfly_url))
                logger.info("Dragonfly Redis connected")
            except Exception as e:
                logger.warning(f"Dragonfly Redis connection failed: {e}")
        if not self.redis_clients:
            logger.warning("No Redis connections available - using in-memory state storage")
        self.vector_memory = VectorMemory()
        self.planner = PlannerModule(self.cerebras, self.xai_client)
        self.critic = CriticModule(self.bedrock, self.cerebras)
        self.multi_agent = MultiAgentCoordinator(self.exa, self.cerebras, self.xai_client, self.bedrock)
        self.state_lock = Lock()
        self.sessions = {}
        self.session_subscribers = {}
        self.research_state = {
            'queries': [],
            'sources': [],
            'insights': [],
            'reasoning_paths': [],
            'status': 'idle',
            'progress': 0,
            'current_action': '',
            'current_phase': '',
            'start_time': None,
            'session_id': None,
            'plan': {},
            'critiques': [],
            'iterations': [],
            'feedback_scores': []
        }

    def generate_session_id(self, query: str) -> str:
        timestamp = str(time.time())
        return hashlib.sha256(f"{query}{timestamp}".encode()).hexdigest()[:16]

    def update_state(self, **kwargs):
        with self.state_lock:
            for key, value in kwargs.items():
                self.research_state[key] = value
            self._persist_state()
            self._broadcast_state()

    def _persist_state(self):
        session_id = self.research_state.get('session_id')
        if session_id:
            with self.state_lock:
                self.sessions[session_id] = dict(self.research_state)
            if self.redis_clients:
                state_json = json.dumps(self.research_state, default=str)
                for redis_client in self.redis_clients:
                    try:
                        redis_client.setex(f"session:{session_id}", 7200, state_json)
                    except Exception as e:
                        logger.debug(f"Redis persist failed: {e}")

    def _broadcast_state(self):
        session_id = self.research_state.get('session_id')
        if session_id:
            state_json = json.dumps(self.research_state, default=str)
            with self.state_lock:
                if session_id in self.session_subscribers:
                    for queue in self.session_subscribers[session_id]:
                        try:
                            queue.put(state_json)
                        except:
                            pass
            if self.redis_clients:
                for redis_client in self.redis_clients:
                    try:
                        redis_client.publish(f"research_updates:{session_id}", state_json)
                    except Exception as e:
                        logger.debug(f"Redis broadcast failed: {e}")

    def get_state(self, session_id: str) -> Dict:
        with self.state_lock:
            if session_id in self.sessions:
                return self.sessions[session_id]
        for redis_client in self.redis_clients:
            try:
                state = redis_client.get(f"session:{session_id}")
                if state:
                    return json.loads(state)
            except Exception as e:
                logger.debug(f"Redis get_state failed: {e}")
                continue
        return {}

    def analyze_with_thinking_models(self, query: str, recalled_context: List[Dict]) -> Dict:
        self.update_state(
            current_action='Deep cognitive analysis with multiple thinking models',
            current_phase='Initial Analysis',
            progress=3
        )
        context_text = "\n".join([f"Memory {i+1}: {item['content']}" for i, item in enumerate(recalled_context[:15])])
        analysis_prompt = f"""You are conducting deep cognitive analysis of a research query.

Query: {query}

Recalled context from previous research:
{context_text}

Perform multi-dimensional analysis:
1. Semantic decomposition: Break down the query into fundamental concepts
2. Causal reasoning: Identify cause-effect relationships to explore
3. Temporal analysis: Historical context and future projections
4. Stakeholder mapping: Who is affected and how
5. Controversy detection: Identify areas of debate or disagreement
6. Knowledge gaps: What is unknown or uncertain
7. Cross-domain connections: Related fields or analogies

Return comprehensive analysis as JSON with all dimensions."""
        analyses = {}
        def analyze_qwen_thinking():
            try:
                response = self.cerebras.chat.completions.create(
                    model="qwen-3-235b-a22b-thinking-2507",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=65000,
                    temperature=0.85
                )
                return {'model': 'qwen-thinking', 'analysis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'qwen-thinking', 'error': str(e)}
        def analyze_gpt_oss():
            try:
                response = self.cerebras.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=65000,
                    temperature=0.8
                )
                return {'model': 'gpt-oss-120b', 'analysis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'gpt-oss-120b', 'error': str(e)}
        def analyze_grok():
            try:
                response = self.xai_client.chat.completions.create(
                    model="grok-4-fast",
                    messages=[{"role": "user", "content": analysis_prompt}],
                    max_tokens=32768,
                    temperature=0.8
                )
                return {'model': 'grok-4-fast', 'analysis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'grok-4-fast', 'error': str(e)}
        with ThreadPoolExecutor(max_workers=3) as executor:
            futures = [
                executor.submit(analyze_qwen_thinking),
                executor.submit(analyze_gpt_oss),
                executor.submit(analyze_grok)
            ]
            for future in as_completed(futures):
                result = future.result()
                analyses[result['model']] = result
        combined_analysis = f"Multi-model analysis:\n\n"
        for model, result in analyses.items():
            combined_analysis += f"--- {model} ---\n{result.get('analysis', result.get('error', ''))}\n\n"
        return {
            'individual_analyses': analyses,
            'combined': combined_analysis
        }

    def dynamic_search_execution(self, plan: Dict, iteration: int) -> Dict:
        self.update_state(
            current_action=f'Executing adaptive search strategies (iteration {iteration})',
            current_phase='Search Execution',
            progress=10 + (iteration * 8)
        )
        strategies = plan.get('search_strategies', [])
        strategies.sort(key=lambda x: x.get('priority', 0), reverse=True)
        all_results = []
        strategy_performance = []
        with ThreadPoolExecutor(max_workers=15) as executor:
            futures = []
            for strategy in strategies[:8]:
                search_query = strategy.get('strategy', '')
                for search_type in ['neural', 'keyword', 'auto']:
                    futures.append(executor.submit(
                        self._execute_single_search,
                        search_query,
                        search_type,
                        strategy
                    ))
            for future in as_completed(futures):
                result = future.result()
                all_results.extend(result['results'])
                strategy_performance.append(result['performance'])
        unique_sources = {}
        for result in all_results:
            url = result.get('url', '')
            if url and url not in unique_sources:
                unique_sources[url] = result
        return {
            'sources': list(unique_sources.values()),
            'performance': strategy_performance,
            'total_found': len(unique_sources)
        }

    def _execute_single_search(self, query: str, search_type: str, strategy: Dict) -> Dict:
        start_time = time.time()
        try:
            result = self.exa.search_and_contents(
                query=query,
                type=search_type,
                num_results=100,
                text=True,
                highlights=True,
                livecrawl="preferred"
            )
            sources = [{
                'url': r.url,
                'title': getattr(r, 'title', ''),
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'published_date': getattr(r, 'published_date', None),
                'author': getattr(r, 'author', None),
                'search_type': search_type,
                'strategy': strategy.get('strategy', '')
            } for r in result.results]
            elapsed = time.time() - start_time
            return {
                'results': sources,
                'performance': {
                    'query': query,
                    'type': search_type,
                    'count': len(sources),
                    'time': elapsed,
                    'strategy': strategy.get('strategy', '')
                }
            }
        except Exception as e:
            return {
                'results': [],
                'performance': {
                    'query': query,
                    'type': search_type,
                    'count': 0,
                    'time': time.time() - start_time,
                    'error': str(e)
                }
            }

    def deep_content_discovery(self, urls: List[str], iteration: int) -> List[Dict]:
        self.update_state(
            current_action=f'Deep content extraction and subpage discovery',
            current_phase='Content Discovery',
            progress=30 + (iteration * 5)
        )
        all_content = []
        def extract_with_subpages(url: str):
            try:
                result = self.exa.get_contents(
                    ids=[url],
                    text=True,
                    highlights=True,
                    summary=True,
                    livecrawl="always",
                    subpages=9,
                    subpage_target=["docs", "documentation", "article", "research", "paper", "guide", "news", "blog", "analysis"]
                )
                return [{
                    'url': r.url if hasattr(r, 'url') else url,
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'summary': getattr(r, 'summary', ''),
                    'type': 'subpage_discovery'
                } for r in result.results]
            except:
                return []
        def find_similar_content(url: str):
            try:
                result = self.exa.find_similar_and_contents(
                    url=url,
                    num_results=100,
                    text=True,
                    highlights=True,
                    exclude_source_domain=True
                )
                return [{
                    'url': r.url,
                    'title': getattr(r, 'title', ''),
                    'text': getattr(r, 'text', ''),
                    'highlights': getattr(r, 'highlights', []),
                    'type': 'similar_content'
                } for r in result.results]
            except:
                return []
        with ThreadPoolExecutor(max_workers=20) as executor:
            futures = []
            for url in urls[:40]:
                futures.append(executor.submit(extract_with_subpages, url))
                futures.append(executor.submit(find_similar_content, url))
            for future in as_completed(futures):
                content = future.result()
                all_content.extend(content)
        return all_content

    def multi_model_synthesis(self, sources: List[Dict], perspective: str, iteration: int) -> Dict:
        self.update_state(
            current_action=f'Multi-model synthesis from {perspective} perspective',
            current_phase='Synthesis',
            progress=50 + (iteration * 4)
        )
        sources_text = "\n\n".join([
            f"[{i+1}] {s.get('title', s.get('url', 'Source'))}\n{s.get('text', '')[:3000]}"
            for i, s in enumerate(sources[:100])
        ])
        synthesis_prompt = f"""Analyze from {perspective} perspective.

Sources:
{sources_text[:50000]}

Provide deep synthesis focusing on {perspective}. Be comprehensive and detailed."""
        syntheses = {}
        def synthesize_gpt_oss():
            try:
                response = self.cerebras.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=[{"role": "user", "content": synthesis_prompt}],
                    max_tokens=32768,
                    temperature=0.7
                )
                return {'model': 'gpt-oss-120b', 'synthesis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'gpt-oss-120b', 'error': str(e)}
        def synthesize_qwen():
            try:
                response = self.cerebras.chat.completions.create(
                    model="qwen-3-235b-a22b-thinking-2507",
                    messages=[{"role": "user", "content": synthesis_prompt}],
                    max_tokens=32768,
                    temperature=0.7
                )
                return {'model': 'qwen-thinking', 'synthesis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'qwen-thinking', 'error': str(e)}
        def synthesize_grok():
            try:
                response = self.xai_client.chat.completions.create(
                    model="grok-4-fast",
                    messages=[{"role": "user", "content": synthesis_prompt}],
                    max_tokens=32768,
                    temperature=0.7
                )
                return {'model': 'grok-4-fast', 'synthesis': response.choices[0].message.content}
            except Exception as e:
                return {'model': 'grok-4-fast', 'error': str(e)}
        def synthesize_claude():
            try:
                if not self.bedrock:
                    return {'model': 'claude-sonnet-4.5', 'error': 'Bedrock not configured'}
                body = json.dumps({
                    "anthropic_version": "bedrock-2023-05-31",
                    "max_tokens": 200000,
                    "messages": [{"role": "user", "content": synthesis_prompt}],
                    "temperature": 0.7
                })
                response = self.bedrock.invoke_model(
                    modelId="anthropic.claude-sonnet-4-5-v2:0",
                    body=body
                )
                response_body = json.loads(response['body'].read())
                return {'model': 'claude-sonnet-4.5', 'synthesis': response_body['content'][0]['text']}
            except Exception as e:
                return {'model': 'claude-sonnet-4.5', 'error': str(e)}
        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = [
                executor.submit(synthesize_gpt_oss),
                executor.submit(synthesize_qwen),
                executor.submit(synthesize_grok),
                executor.submit(synthesize_claude)
            ]
            for future in as_completed(futures):
                result = future.result()
                syntheses[result['model']] = result
        return {
            'perspective': perspective,
            'models': syntheses
        }

    def iterative_refinement_loop(self, query: str, initial_plan: Dict, max_iterations: int = 10) -> Dict:
        all_sources = []
        all_syntheses = []
        iteration_history = []
        current_plan = initial_plan
        for iteration in range(max_iterations):
            self.update_state(
                current_action=f'Refinement iteration {iteration + 1}/{max_iterations}',
                current_phase=f'Iteration {iteration + 1}',
                progress=60 + (iteration * 3)
            )
            search_results = self.dynamic_search_execution(current_plan, iteration)
            new_sources = search_results['sources']
            all_sources.extend(new_sources)
            unique_sources = {}
            for source in all_sources:
                url = source.get('url', '')
                if url:
                    unique_sources[url] = source
            all_sources = list(unique_sources.values())
            if iteration % 2 == 0:
                urls_to_expand = [s['url'] for s in new_sources[:30]]
                expanded_content = self.deep_content_discovery(urls_to_expand, iteration)
                all_sources.extend(expanded_content)
            perspectives = [
                'technical and scientific',
                'business and economic',
                'social and ethical',
                'future trends and predictions',
                'risks and challenges'
            ]
            perspective = perspectives[iteration % len(perspectives)]
            synthesis = self.multi_model_synthesis(all_sources[-200:], perspective, iteration)
            all_syntheses.append(synthesis)
            iteration_summary = {
                'iteration': iteration + 1,
                'sources_found': len(new_sources),
                'total_sources': len(all_sources),
                'perspective': perspective,
                'performance': search_results.get('performance', [])
            }
            iteration_history.append(iteration_summary)
            if iteration < max_iterations - 1 and iteration % 3 == 2:
                execution_results = {
                    'iterations': iteration_history,
                    'sources_count': len(all_sources),
                    'synthesis_summary': all_syntheses[-1]
                }
                current_plan = self.planner.replan(current_plan, execution_results, iteration)
                self.update_state(
                    current_action='Plan updated based on findings',
                    plan=current_plan
                )
            if len(all_sources) > 800:
                break
        return {
            'sources': all_sources,
            'syntheses': all_syntheses,
            'iterations': iteration_history,
            'final_plan': current_plan
        }

