    def autonomous_cognitive_research(self, query: str, max_duration_minutes: int = 90) -> Dict:
        session_id = self.generate_session_id(query)
        start_time = time.time()
        self.update_state(
            session_id=session_id,
            status='running',
            start_time=start_time,
            progress=0,
            current_action='Initializing cognitive research system',
            current_phase='Initialization'
        )
        try:
            recalled_memories = self.vector_memory.recall_similar(query, top_k=20)
            self.update_state(
                current_action=f'Recalled {len(recalled_memories)} relevant memories',
                progress=1
            )
            deep_analysis = self.analyze_with_thinking_models(query, recalled_memories)
            research_plan = self.planner.create_research_plan(query, recalled_memories)
            self.update_state(
                plan=research_plan,
                current_action='Strategic research plan created',
                progress=8
            )
            multi_agent_results = self.multi_agent.coordinate_research(query, research_plan)
            refinement_results = self.iterative_refinement_loop(query, research_plan, max_iterations=12)
            all_sources = multi_agent_results['sources'] + refinement_results['sources']
            unique_sources = {}
            for source in all_sources:
                url = source.get('url', '')
                if url:
                    unique_sources[url] = source
            all_sources = list(unique_sources.values())
            self.update_state(
                sources=all_sources[:500],
                current_action=f'Collected {len(all_sources)} unique sources',
                progress=85
            )
            preliminary_findings = multi_agent_results['synthesis'] + "\n\n" + "\n\n".join([
                f"{s.get('perspective', '')}: {list(s.get('models', {}).values())[0].get('synthesis', '')[:2000]}"
                for s in refinement_results['syntheses'][:3]
            ])
            critique = self.critic.critique_findings(preliminary_findings, all_sources[:100])
            defense = self.critic.defend_or_revise(preliminary_findings, critique)
            critique_cycle = {
                'critique': critique,
                'defense': defense
            }
            self.update_state(
                critiques=[critique_cycle],
                current_action='Critique and defense cycle completed',
                progress=88
            )
            final_report = self.generate_comprehensive_report(
                query,
                {
                    'sources': all_sources,
                    'syntheses': refinement_results['syntheses'],
                    'multi_agent': multi_agent_results
                },
                critique_cycle
            )
            self.vector_memory.store_insight(
                f"Research: {query}\n\nKey findings: {final_report[:2000]}",
                {
                    'type': 'research',
                    'query': query,
                    'sources_count': len(all_sources),
                    'session_id': session_id
                }
            )
            self.update_state(
                status='completed',
                progress=100,
                current_action='Research completed successfully',
                current_phase='Completed'
            )
            result = {
                'session_id': session_id,
                'query': query,
                'report': final_report,
                'metadata': {
                    'total_sources': len(all_sources),
                    'unique_urls': len(unique_sources),
                    'iterations': len(refinement_results['iterations']),
                    'duration_seconds': time.time() - start_time,
                    'models_used': ['gpt-oss-120b', 'qwen-3-235b-thinking', 'grok-4-fast', 'claude-sonnet-4.5'],
                    'plan': research_plan,
                    'critique': critique_cycle
                },
                'sources': all_sources[:200]
            }
            with self.state_lock:
                self.sessions[f"report:{session_id}"] = result
            for redis_client in self.redis_clients:
                try:
                    redis_client.setex(f"report:{session_id}", 86400, json.dumps(result, default=str))
                except Exception as e:
                    logger.debug(f"Redis report save failed: {e}")
            return result
        except Exception as e:
            self.update_state(
                status='error',
                current_action=f'Error: {str(e)}',
                current_phase='Error'
            )
            return {
                'session_id': session_id,
                'error': str(e),
                'partial_state': self.research_state
            }

