class MetricsCollector:
    def __init__(self):
        self.task_counter = Counter('tasks_total', 'Total tasks processed', ['task_type', 'status'])
        self.task_duration = Histogram('task_duration_seconds', 'Task processing duration', ['task_type'])
        self.active_agents = Gauge('active_agents', 'Number of active agents', ['role'])
        self.memory_usage = Gauge('memory_usage_bytes', 'Memory usage in bytes')
        self.source_counter = Counter('sources_retrieved', 'Sources retrieved', ['search_type'])
        self.model_usage = Counter('model_invocations', 'Model API calls', ['model', 'status'])
        self.cache_hits = Counter('cache_hits', 'Cache hit/miss', ['result'])

    def record_task(self, task_type: str, duration: float, status: str):
        self.task_counter.labels(task_type=task_type, status=status).inc()
        self.task_duration.labels(task_type=task_type).observe(duration)

    def update_memory(self):
        process = psutil.Process()
        self.memory_usage.set(process.memory_info().rss)

