class DistributedCache:
    def __init__(self, redis_clients: List[redis.Redis], ttl: int = 3600):
        self.redis_clients = redis_clients
        self.ttl = ttl
        self.local_cache = {}
        self.local_cache_lock = Lock()
        self.max_local_size = 10000

    def get(self, key: str) -> Optional[Any]:
        with self.local_cache_lock:
            if key in self.local_cache:
                value, expiry = self.local_cache[key]
                if time.time() < expiry:
                    return value
                else:
                    del self.local_cache[key]
        for redis_client in self.redis_clients:
            try:
                data = redis_client.get(f"cache:{key}")
                if data:
                    value = msgpack.unpackb(lz4.frame.decompress(data), raw=False)
                    self._set_local(key, value)
                    return value
            except Exception as e:
                logger.debug(f"Cache get error: {e}")
                continue
        return None

    def set(self, key: str, value: Any, ttl: Optional[int] = None):
        ttl = ttl or self.ttl
        self._set_local(key, value, ttl)
        serialized = lz4.frame.compress(msgpack.packb(value, use_bin_type=True))
        for redis_client in self.redis_clients:
            try:
                redis_client.setex(f"cache:{key}", ttl, serialized)
            except Exception as e:
                logger.debug(f"Cache set error: {e}")

    def _set_local(self, key: str, value: Any, ttl: Optional[int] = None):
        ttl = ttl or self.ttl
        with self.local_cache_lock:
            if len(self.local_cache) >= self.max_local_size:
                oldest_key = min(self.local_cache.keys(), key=lambda k: self.local_cache[k][1])
                del self.local_cache[oldest_key]
            self.local_cache[key] = (value, time.time() + ttl)

    def invalidate(self, pattern: str):
        with self.local_cache_lock:
            keys_to_delete = [k for k in self.local_cache.keys() if pattern in k]
            for key in keys_to_delete:
                del self.local_cache[key]
        for redis_client in self.redis_clients:
            try:
                for key in redis_client.scan_iter(match=f"cache:*{pattern}*"):
                    redis_client.delete(key)
            except Exception as e:
                logger.debug(f"Cache invalidate error: {e}")

class VectorMemorySystem:
    def __init__(self, embedding_dim: int = 384):
        self.index = None
        self.embedding_model = None
        self.embedding_dim = embedding_dim
        self.memory_graph = nx.DiGraph()
        self.memory_lock = Lock()
        try:
            self.pinecone_client = Pinecone(api_key=os.getenv('PINECONE_API_KEY'))
            self.embedding_model = SentenceTransformer('all-MiniLM-L6-v2')
            try:
                self.index = self.pinecone_client.Index('cognitive-ultra')
                logger.info("Pinecone vector memory initialized")
            except Exception as e:
                logger.warning(f"Creating Pinecone index: {e}")
                self.pinecone_client.create_index(
                    name='cognitive-ultra',
                    dimension=self.embedding_dim,
                    metric='cosine',
                    spec=ServerlessSpec(cloud='aws', region=os.getenv('PINECONE_REGION', 'us-east-1'))
                )
                time.sleep(60)
                self.index = self.pinecone_client.Index('cognitive-ultra')
        except Exception as e:
            logger.warning(f"Pinecone init failed: {e}")

    def store_memory(self, content: str, metadata: Dict, relationships: List[str] = None) -> str:
        if not self.index or not self.embedding_model:
            return None
        try:
            memory_id = hashlib.sha256(f"{content}{time.time()}".encode()).hexdigest()
            embedding = self.embedding_model.encode(content).tolist()
            self.index.upsert(vectors=[{
                'id': memory_id,
                'values': embedding,
                'metadata': {**metadata, 'content': content[:2000], 'timestamp': time.time(), 'access_count': 0}
            }])
            with self.memory_lock:
                self.memory_graph.add_node(memory_id, content=content[:500], metadata=metadata)
                if relationships:
                    for related_id in relationships:
                        if self.memory_graph.has_node(related_id):
                            self.memory_graph.add_edge(memory_id, related_id, weight=1.0)
            return memory_id
        except Exception as e:
            logger.error(f"Memory store error: {e}")
            return None

    def recall_memories(self, query: str, top_k: int = 50, use_graph: bool = True) -> List[Dict]:
        if not self.index or not self.embedding_model:
            return []
        try:
            query_embedding = self.embedding_model.encode(query).tolist()
            results = self.index.query(vector=query_embedding, top_k=top_k, include_metadata=True)
            memories = []
            for match in results.matches:
                memory_data = {
                    'id': match.id,
                    'content': match.metadata.get('content', ''),
                    'score': match.score,
                    'metadata': match.metadata
                }
                memories.append(memory_data)
                try:
                    self.index.update(id=match.id, set_metadata={'access_count': match.metadata.get('access_count', 0) + 1})
                except:
                    pass
            if use_graph and memories:
                with self.memory_lock:
                    expanded_memories = set()
                    for memory in memories[:10]:
                        memory_id = memory['id']
                        if self.memory_graph.has_node(memory_id):
                            neighbors = list(self.memory_graph.neighbors(memory_id))
                            expanded_memories.update(neighbors[:5])
                    for neighbor_id in expanded_memories:
                        if self.memory_graph.has_node(neighbor_id):
                            node_data = self.memory_graph.nodes[neighbor_id]
                            memories.append({
                                'id': neighbor_id,
                                'content': node_data.get('content', ''),
                                'score': 0.7,
                                'metadata': node_data.get('metadata', {}),
                                'type': 'graph_expansion'
                            })
            return memories
        except Exception as e:
            logger.error(f"Memory recall error: {e}")
            return []

    def consolidate_memories(self, threshold: float = 0.85):
        if not self.index:
            return
        try:
            stats = self.index.describe_index_stats()
            total_vectors = stats.total_vector_count
            if total_vectors < 1000:
                return
            sample_ids = []
            for _ in range(min(100, total_vectors)):
                sample_ids.append(str(uuid.uuid4()))
            for vector_id in sample_ids:
                try:
                    fetch_result = self.index.fetch(ids=[vector_id])
                    if fetch_result.vectors:
                        vector = fetch_result.vectors[vector_id]
                        similar = self.index.query(vector=vector.values, top_k=10, include_metadata=True)
                        for match in similar.matches[1:]:
                            if match.score > threshold:
                                self.index.delete(ids=[match.id])
                except:
                    continue
        except Exception as e:
            logger.error(f"Memory consolidation error: {e}")

class TaskOrchestrator:
    def __init__(self):
        self.task_queue = PriorityQueue()
        self.task_graph = nx.DiGraph()
        self.completed_tasks = {}
        self.failed_tasks = {}
        self.running_tasks = {}
        self.task_lock = Lock()
        self.agents = {}
        self.agent_pool_lock = Lock()

    def submit_task(self, task: Task) -> str:
        with self.task_lock:
            self.task_graph.add_node(task.task_id, task=task)
            for dep in task.dependencies:
                self.task_graph.add_edge(dep, task.task_id)
            if not task.dependencies or all(dep in self.completed_tasks for dep in task.dependencies):
                self.task_queue.put((task.priority.value, task.task_id, task))
        return task.task_id

    def get_next_task(self, agent_capabilities: List[str]) -> Optional[Task]:
        with self.task_lock:
            available_tasks = []
            temp_queue = PriorityQueue()
            while not self.task_queue.empty():
                priority, task_id, task = self.task_queue.get()
                if task.task_type in agent_capabilities or '*' in agent_capabilities:
                    if all(dep in self.completed_tasks for dep in task.dependencies):
                        available_tasks.append((priority, task_id, task))
                    else:
                        temp_queue.put((priority, task_id, task))
                else:
                    temp_queue.put((priority, task_id, task))
            while not temp_queue.empty():
                self.task_queue.put(temp_queue.get())
            if available_tasks:
                available_tasks.sort(key=lambda x: x[0])
                _, task_id, task = available_tasks[0]
                task.started_at = time.time()
                self.running_tasks[task_id] = task
                for remaining in available_tasks[1:]:
                    self.task_queue.put(remaining)
                return task
        return None

    def complete_task(self, task_id: str, result: Any):
        with self.task_lock:
            if task_id in self.running_tasks:
                task = self.running_tasks[task_id]
                task.completed_at = time.time()
                task.result = result
                self.completed_tasks[task_id] = task
                del self.running_tasks[task_id]
                successors = list(self.task_graph.successors(task_id))
                for successor_id in successors:
                    successor_task = self.task_graph.nodes[successor_id]['task']
                    if all(dep in self.completed_tasks for dep in successor_task.dependencies):
                        self.task_queue.put((successor_task.priority.value, successor_id, successor_task))

    def fail_task(self, task_id: str, error: str):
        with self.task_lock:
            if task_id in self.running_tasks:
                task = self.running_tasks[task_id]
                task.retry_count += 1
                if task.retry_count < task.max_retries:
                    task.error = None
                    self.task_queue.put((task.priority.value, task_id, task))
                else:
                    task.error = error
                    task.completed_at = time.time()
                    self.failed_tasks[task_id] = task
                del self.running_tasks[task_id]

    def register_agent(self, agent_state: AgentState):
        with self.agent_pool_lock:
            self.agents[agent_state.agent_id] = agent_state

    def get_task_status(self, task_id: str) -> Dict:
        with self.task_lock:
            if task_id in self.completed_tasks:
                return {'status': 'completed', 'task': asdict(self.completed_tasks[task_id])}
            elif task_id in self.running_tasks:
                return {'status': 'running', 'task': asdict(self.running_tasks[task_id])}
            elif task_id in self.failed_tasks:
                return {'status': 'failed', 'task': asdict(self.failed_tasks[task_id])}
        return {'status': 'not_found'}

class ModelRouter:
    def __init__(self, cerebras: Cerebras, xai: OpenAI, bedrock):
        self.cerebras = cerebras
        self.xai = xai
        self.bedrock = bedrock
        self.model_stats = defaultdict(lambda: {'calls': 0, 'total_tokens': 0, 'errors': 0, 'avg_latency': 0.0})
        self.stats_lock = Lock()

    def route_request(self, prompt: str, task_type: str, context_size: int, priority: TaskPriority, max_tokens: int = 32768) -> Tuple[str, Dict]:
        model_selection = self._select_optimal_model(task_type, context_size, priority)
        model_name = model_selection['model']
        start_time = time.time()
        try:
            if model_name.startswith('qwen'):
                response = self.cerebras.chat.completions.create(
                    model=model_name,
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=min(max_tokens, 65000),
                    temperature=model_selection.get('temperature', 0.7)
                )
                result = response.choices[0].message.content
                tokens_used = getattr(response.usage, 'total_tokens', 0) if hasattr(response, 'usage') else 0
            elif model_name.startswith('gpt-oss'):
                response = self.cerebras.chat.completions.create(
                    model=model_name,
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=min(max_tokens, 65000),
                    temperature=model_selection.get('temperature', 0.7)
                )
                result = response.choices[0].message.content
                tokens_used = getattr(response.usage, 'total_tokens', 0) if hasattr(response, 'usage') else 0
            elif model_name.startswith('grok'):
                response = self.xai.chat.completions.create(
                    model=model_name,
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=min(max_tokens, 131072),
                    temperature=model_selection.get('temperature', 0.7)
                )
                result = response.choices[0].message.content
                tokens_used = getattr(response.usage, 'total_tokens', 0) if hasattr(response, 'usage') else 0
            elif model_name.startswith('claude') and self.bedrock:
                body = json.dumps({
                    "anthropic_version": "bedrock-2023-05-31",
                    "max_tokens": min(max_tokens, 200000),
                    "messages": [{"role": "user", "content": prompt}],
                    "temperature": model_selection.get('temperature', 0.7)
                })
                response = self.bedrock.invoke_model(modelId="anthropic.claude-sonnet-4-5-v2:0", body=body)
                response_body = json.loads(response['body'].read())
                result = response_body['content'][0]['text']
                tokens_used = response_body.get('usage', {}).get('input_tokens', 0) + response_body.get('usage', {}).get('output_tokens', 0)
            else:
                result = f"Error: Unknown model {model_name}"
                tokens_used = 0
            latency = time.time() - start_time
            self._update_stats(model_name, tokens_used, latency, success=True)
            return result, {'model': model_name, 'tokens': tokens_used, 'latency': latency}
        except Exception as e:
            self._update_stats(model_name, 0, time.time() - start_time, success=False)
            return f"Error: {str(e)}", {'model': model_name, 'error': str(e)}

    def _select_optimal_model(self, task_type: str, context_size: int, priority: TaskPriority) -> Dict:
        if context_size > 100000:
            return {'model': 'grok-4-fast', 'temperature': 0.7, 'reason': 'large_context'}
        if task_type in ['reasoning', 'planning', 'complex_analysis']:
            if priority == TaskPriority.CRITICAL:
                return {'model': 'qwen-3-235b-a22b-thinking-2507', 'temperature': 0.85, 'reason': 'critical_reasoning'}
            else:
                return {'model': 'gpt-oss-120b', 'temperature': 0.75, 'reason': 'reasoning'}
        if task_type in ['synthesis', 'report', 'comprehensive']:
            return {'model': 'claude-sonnet-4.5', 'temperature': 0.65, 'reason': 'synthesis'}
        if task_type in ['quick', 'classification', 'extraction']:
            return {'model': 'gpt-oss-120b', 'temperature': 0.6, 'reason': 'speed'}
        return {'model': 'gpt-oss-120b', 'temperature': 0.7, 'reason': 'default'}

    def _update_stats(self, model: str, tokens: int, latency: float, success: bool):
        with self.stats_lock:
            stats = self.model_stats[model]
            stats['calls'] += 1
            if not success:
                stats['errors'] += 1
            else:
                stats['total_tokens'] += tokens
                current_avg = stats['avg_latency']
                stats['avg_latency'] = (current_avg * (stats['calls'] - 1) + latency) / stats['calls']

class ParallelSearchEngine:
    def __init__(self, exa: Exa, cache: DistributedCache, max_workers: int = 30):
        self.exa = exa
        self.cache = cache
        self.max_workers = max_workers

    def execute_search_strategy(self, queries: List[str], search_config: Dict) -> List[Dict]:
        all_results = []
        seen_urls = set()
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = []
            for query in queries:
                for search_type in search_config.get('search_types', ['neural', 'keyword', 'auto']):
                    cache_key = hashlib.sha256(f"{query}:{search_type}".encode()).hexdigest()
                    cached = self.cache.get(cache_key)
                    if cached:
                        all_results.extend(cached)
                        continue
                    futures.append(executor.submit(self._single_search, query, search_type, search_config, cache_key))
            for future in as_completed(futures):
                try:
                    results = future.result(timeout=60)
                    for result in results:
                        url = result.get('url', '')
                        if url and url not in seen_urls:
                            seen_urls.add(url)
                            all_results.append(result)
                except Exception as e:
                    logger.error(f"Search future error: {e}")
        return all_results

    def _single_search(self, query: str, search_type: str, config: Dict, cache_key: str) -> List[Dict]:
        try:
            result = self.exa.search_and_contents(
                query=query,
                type=search_type,
                num_results=config.get('num_results', 100),
                text=True,
                highlights=True,
                livecrawl=config.get('livecrawl', 'preferred'),
                **config.get('extra_params', {})
            )
            sources = [{
                'url': r.url,
                'title': getattr(r, 'title', ''),
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'published_date': getattr(r, 'published_date', None),
                'author': getattr(r, 'author', None),
                'search_type': search_type,
                'query': query
            } for r in result.results]
            self.cache.set(cache_key, sources, ttl=1800)
            return sources
        except Exception as e:
            logger.error(f"Search error for {query} ({search_type}): {e}")
            return []

    def deep_content_extraction(self, urls: List[str], config: Dict) -> List[Dict]:
        all_content = []
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = []
            for url in urls[:config.get('max_urls', 100)]:
                futures.append(executor.submit(self._extract_content, url, config))
                if config.get('find_similar', False):
                    futures.append(executor.submit(self._find_similar, url, config))
            for future in as_completed(futures):
                try:
                    content = future.result(timeout=45)
                    all_content.extend(content)
                except Exception as e:
                    logger.debug(f"Content extraction error: {e}")
        return all_content

    def _extract_content(self, url: str, config: Dict) -> List[Dict]:
        try:
            result = self.exa.get_contents(
                ids=[url],
                text=True,
                highlights=True,
                summary=True,
                livecrawl=config.get('livecrawl', 'always'),
                subpages=config.get('subpages', 9)
            )
            return [{
                'url': r.url if hasattr(r, 'url') else url,
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'summary': getattr(r, 'summary', ''),
                'type': 'extracted'
            } for r in result.results]
        except:
            return []

    def _find_similar(self, url: str, config: Dict) -> List[Dict]:
        try:
            result = self.exa.find_similar_and_contents(
                url=url,
                num_results=config.get('similar_count', 50),
                text=True,
                highlights=True,
                exclude_source_domain=True
            )
            return [{
                'url': r.url,
                'title': getattr(r, 'title', ''),
                'text': getattr(r, 'text', ''),
                'highlights': getattr(r, 'highlights', []),
                'type': 'similar'
            } for r in result.results]
        except:
            return []

class AdvancedPlanningEngine:
    def __init__(self, model_router: ModelRouter, memory: VectorMemorySystem):
        self.router = model_router
        self.memory = memory

    def create_multi_phase_plan(self, query: str, context: List[Dict], constraints: Dict) -> Dict:
        memories = self.memory.recall_memories(query, top_k=30)
        context_text = "\n".join([f"- {m['content'][:300]}" for m in memories[:15]])
        planning_prompt = f"""Create an advanced multi-phase research plan with adaptive strategies.

Query: {query}

Constraints: {json.dumps(constraints, indent=2)}

Relevant memories:
{context_text}

Create a sophisticated plan with:
1. Strategic objectives (5-7 specific, measurable goals)
2. Multi-dimensional search strategies with priorities
3. Parallel execution paths
4. Contingency scenarios
5. Quality gates and validation checkpoints
6. Resource allocation plan
7. Risk assessment and mitigation
8. Expected timeline and milestones

Return as detailed JSON."""
        result, metadata = self.router.route_request(
            planning_prompt,
            task_type='planning',
            context_size=len(planning_prompt),
            priority=TaskPriority.HIGH,
            max_tokens=65000
        )
        try:
            plan = json.loads(result)
        except:
            plan = {
                'objectives': [query],
                'search_strategies': [{'strategy': 'comprehensive', 'priority': 5}],
                'execution_phases': [{'phase': 'research', 'tasks': ['search', 'analyze']}],
                'contingencies': []
            }
        self.memory.store_memory(f"Plan for: {query}\n{json.dumps(plan, indent=2)[:1000]}", {'type': 'plan', 'query': query})
        return plan

    def adaptive_replan(self, original_plan: Dict, execution_history: List[Dict], iteration: int) -> Dict:
        history_summary = json.dumps(execution_history[-5:], indent=2)[:3000]
        replan_prompt = f"""Analyze execution results and create improved plan.

Original objectives: {json.dumps(original_plan.get('objectives', []))}
Iteration: {iteration}
Recent execution: {history_summary}

Create updated plan that:
- Reinforces successful strategies
- Eliminates ineffective approaches
- Introduces new angles based on findings
- Optimizes resource allocation
- Adjusts priorities dynamically

Return updated plan JSON."""
        result, metadata = self.router.route_request(
            replan_prompt,
            task_type='planning',
            context_size=len(replan_prompt),
            priority=TaskPriority.MEDIUM,
            max_tokens=32768
        )
        try:
            return json.loads(result)
        except:
            return original_plan

class MultiAgentSystem:
    def __init__(self, orchestrator: TaskOrchestrator, router: ModelRouter, search: ParallelSearchEngine, memory: VectorMemorySystem):
        self.orchestrator = orchestrator
        self.router = router
        self.search = search
        self.memory = memory
        self.agent_threads = []
        self.shutdown_event = Event()

    def spawn_agent(self, role: AgentRole, capabilities: List[str], count: int = 1):
        for i in range(count):
            agent_state = AgentState(
                agent_id=f"{role.value}_{uuid.uuid4().hex[:8]}",
                role=role,
                status='idle',
                capabilities=capabilities
            )
            self.orchestrator.register_agent(agent_state)
            thread = Thread(target=self._agent_worker, args=(agent_state,), daemon=True)
            thread.start()
            self.agent_threads.append(thread)

    def _agent_worker(self, agent_state: AgentState):
        while not self.shutdown_event.is_set():
            try:
                task = self.orchestrator.get_next_task(agent_state.capabilities)
                if not task:
                    time.sleep(0.5)
                    continue
                agent_state.status = 'working'
                agent_state.current_task = task.task_id
                start_time = time.time()
                try:
                    result = self._execute_task(task, agent_state)
                    self.orchestrator.complete_task(task.task_id, result)
                    agent_state.tasks_completed += 1
                except Exception as e:
                    self.orchestrator.fail_task(task.task_id, str(e))
                    agent_state.tasks_failed += 1
                    logger.error(f"Agent {agent_state.agent_id} task failed: {e}")
                processing_time = time.time() - start_time
                agent_state.total_processing_time += processing_time
                agent_state.status = 'idle'
                agent_state.current_task = None
                agent_state.last_heartbeat = time.time()
            except Exception as e:
                logger.error(f"Agent worker error: {e}")
                time.sleep(1)

    def _execute_task(self, task: Task, agent_state: AgentState) -> Any:
        task_type = task.task_type
        payload = task.payload
        if task_type == 'search':
            return self._execute_search_task(payload)
        elif task_type == 'analyze':
            return self._execute_analysis_task(payload)
        elif task_type == 'synthesize':
            return self._execute_synthesis_task(payload)
        elif task_type == 'critique':
            return self._execute_critique_task(payload)
        elif task_type == 'extract':
            return self._execute_extraction_task(payload)
        else:
            raise ValueError(f"Unknown task type: {task_type}")

    def _execute_search_task(self, payload: Dict) -> Dict:
        queries = payload.get('queries', [])
        config = payload.get('config', {'search_types': ['neural', 'keyword'], 'num_results': 100})
        results = self.search.execute_search_strategy(queries, config)
        return {'sources': results, 'count': len(results)}

    def _execute_analysis_task(self, payload: Dict) -> Dict:
        content = payload.get('content', '')
        analysis_type = payload.get('analysis_type', 'general')
        prompt = f"Analyze the following from {analysis_type} perspective:\n\n{content[:30000]}"
        result, metadata = self.router.route_request(prompt, 'analysis', len(prompt), TaskPriority.MEDIUM)
        return {'analysis': result, 'metadata': metadata}

    def _execute_synthesis_task(self, payload: Dict) -> Dict:
        sources = payload.get('sources', [])
        perspective = payload.get('perspective', 'comprehensive')
        sources_text = "\n\n".join([f"{s.get('title', '')}: {s.get('text', '')[:2000]}" for s in sources[:100]])
        prompt = f"Synthesize from {perspective} perspective:\n\n{sources_text}"
        result, metadata = self.router.route_request(prompt, 'synthesis', len(prompt), TaskPriority.MEDIUM, max_tokens=65000)
        return {'synthesis': result, 'metadata': metadata}

    def _execute_critique_task(self, payload: Dict) -> Dict:
        content = payload.get('content', '')
        prompt = f"Critically analyze and find flaws:\n\n{content[:20000]}"
        result, metadata = self.router.route_request(prompt, 'reasoning', len(prompt), TaskPriority.LOW)
        return {'critique': result, 'metadata': metadata}

    def _execute_extraction_task(self, payload: Dict) -> Dict:
        urls = payload.get('urls', [])
        config = payload.get('config', {'max_urls': 50, 'subpages': 9})
        content = self.search.deep_content_extraction(urls, config)
        return {'extracted': content, 'count': len(content)}

class CognitiveResearchSystem:
    def __init__(self):
        logger.info("Initializing Ultra-Advanced Cognitive Research System")
        self.exa = Exa(api_key=os.getenv('EXA_API_KEY'))
        self.cerebras = Cerebras(api_key=os.getenv('CEREBRAS_API_KEY'))
        self.xai = OpenAI(base_url="", api_key=os.getenv('XAI_API_KEY'))
        self.bedrock = None
        if os.getenv('AWS_ACCESS_KEY_ID') and os.getenv('AWS_SECRET_ACCESS_KEY'):
            try:
                self.bedrock = boto3.client(
                    'bedrock-runtime',
                    region_name=os.getenv('AWS_REGION', 'us-east-1'),
                    aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
                    aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY')
                )
            except Exception as e:
                logger.warning(f"Bedrock init failed: {e}")
        self.redis_clients = []
        for redis_url_env in ['UPSTASH_REDIS_REST_URL', 'DRAGONFLY_REDIS_URL', 'REDIS_URL']:
            redis_url = os.getenv(redis_url_env)
            if redis_url and redis_url.startswith(('redis://', 'rediss://')):
                try:
                    self.redis_clients.append(redis.from_url(redis_url))
                    logger.info(f"Connected to Redis: {redis_url_env}")
                except Exception as e:
                    logger.warning(f"Redis connection failed for {redis_url_env}: {e}")
        self.cache = DistributedCache(self.redis_clients)
        self.memory = VectorMemorySystem()
        self.orchestrator = TaskOrchestrator()
        self.router = ModelRouter(self.cerebras, self.xai, self.bedrock)
        self.search_engine = ParallelSearchEngine(self.exa, self.cache, max_workers=40)
        self.planner = AdvancedPlanningEngine(self.router, self.memory)
        self.multi_agent = MultiAgentSystem(self.orchestrator, self.router, self.search_engine, self.memory)
        self.metrics = MetricsCollector()
        self.sessions = {}
        self.session_lock = Lock()
        self._initialize_agent_pool()

    def _initialize_agent_pool(self):
        self.multi_agent.spawn_agent(AgentRole.RESEARCHER, ['search', 'extract'], count=5)
        self.multi_agent.spawn_agent(AgentRole.ANALYST, ['analyze'], count=3)
        self.multi_agent.spawn_agent(AgentRole.SYNTHESIZER, ['synthesize'], count=2)
        self.multi_agent.spawn_agent(AgentRole.CRITIC, ['critique'], count=1)
        logger.info("Agent pool initialized with 11 agents")

    def execute_research(self, query: str, config: Dict = None) -> Dict:
        session_id = hashlib.sha256(f"{query}{time.time()}".encode()).hexdigest()[:16]
        start_time = time.time()
        config = config or {}
        session_state = {
            'session_id': session_id,
            'query': query,
            'status': 'running',
            'progress': 0,
            'start_time': start_time,
            'current_phase': 'initialization',
            'phases': []
        }
        with self.session_lock:
            self.sessions[session_id] = session_state
        try:
            self._update_session(session_id, progress=5, current_phase='memory_recall')
            memories = self.memory.recall_memories(query, top_k=50, use_graph=True)
            self._update_session(session_id, progress=10, current_phase='planning')
            plan = self.planner.create_multi_phase_plan(query, memories, config.get('constraints', {}))
            self._update_session(session_id, progress=15, current_phase='parallel_search', plan=plan)
            search_tasks = []
            for i, strategy in enumerate(plan.get('search_strategies', [])[:10]):
                task = Task(
                    task_id=f"search_{session_id}_{i}",
                    task_type='search',
                    priority=TaskPriority.HIGH if i < 3 else TaskPriority.MEDIUM,
                    payload={
                        'queries': [strategy.get('strategy', query)],
                        'config': {'search_types': ['neural', 'keyword', 'auto'], 'num_results': 100}
                    }
                )
                search_tasks.append(task.task_id)
                self.orchestrator.submit_task(task)
            self._wait_for_tasks(search_tasks, timeout=120)
            all_sources = []
            for task_id in search_tasks:
                task_result = self.orchestrator.completed_tasks.get(task_id)
                if task_result and task_result.result:
                    all_sources.extend(task_result.result.get('sources', []))
            unique_sources = {s['url']: s for s in all_sources if s.get('url')}
            all_sources = list(unique_sources.values())
            self._update_session(session_id, progress=40, current_phase='deep_extraction')
            extraction_tasks = []
            for i, url_batch in enumerate([all_sources[j:j+20] for j in range(0, min(len(all_sources), 200), 20)]):
                task = Task(
                    task_id=f"extract_{session_id}_{i}",
                    task_type='extract',
                    priority=TaskPriority.MEDIUM,
                    payload={
                        'urls': [s['url'] for s in url_batch],
                        'config': {'max_urls': 20, 'subpages': 9, 'find_similar': True}
                    }
                )
                extraction_tasks.append(task.task_id)
                self.orchestrator.submit_task(task)
            self._wait_for_tasks(extraction_tasks, timeout=180)
            for task_id in extraction_tasks:
                task_result = self.orchestrator.completed_tasks.get(task_id)
                if task_result and task_result.result:
                    all_sources.extend(task_result.result.get('extracted', []))
            unique_sources = {s.get('url', str(uuid.uuid4())): s for s in all_sources}
            all_sources = list(unique_sources.values())
            self._update_session(session_id, progress=60, current_phase='multi_perspective_analysis')
            perspectives = ['technical', 'business', 'social', 'ethical', 'future_trends', 'risks']
            analysis_tasks = []
            for i, perspective in enumerate(perspectives):
                task = Task(
                    task_id=f"synthesize_{session_id}_{i}",
                    task_type='synthesize',
                    priority=TaskPriority.MEDIUM,
                    payload={
                        'sources': all_sources[:200],
                        'perspective': perspective
                    }
                )
                analysis_tasks.append(task.task_id)
                self.orchestrator.submit_task(task)
            self._wait_for_tasks(analysis_tasks, timeout=240)
            syntheses = []
            for task_id in analysis_tasks:
                task_result = self.orchestrator.completed_tasks.get(task_id)
                if task_result and task_result.result:
                    syntheses.append(task_result.result)
            self._update_session(session_id, progress=80, current_phase='critical_review')
            combined_synthesis = "\n\n".join([s.get('synthesis', '')[:5000] for s in syntheses])
            critique_task = Task(
                task_id=f"critique_{session_id}",
                task_type='critique',
                priority=TaskPriority.LOW,
                payload={'content': combined_synthesis}
            )
            self.orchestrator.submit_task(critique_task)
            self._wait_for_tasks([critique_task.task_id], timeout=120)
            critique_result = self.orchestrator.completed_tasks.get(critique_task.task_id)
            critique = critique_result.result if critique_result else {}
            self._update_session(session_id, progress=90, current_phase='final_report')
            final_report = self._generate_comprehensive_report(query, all_sources, syntheses, critique, plan)
            self.memory.store_memory(
                f"Research: {query}\n\nFindings: {final_report[:3000]}",
                {'type': 'research', 'session_id': session_id, 'sources': len(all_sources)}
            )
            duration = time.time() - start_time
            result = {
                'session_id': session_id,
                'query': query,
                'report': final_report,
                'metadata': {
                    'total_sources': len(all_sources),
                    'unique_sources': len(unique_sources),
                    'syntheses_count': len(syntheses),
                    'duration_seconds': duration,
                    'plan': plan,
                    'critique': critique
                },
                'sources': all_sources[:500]
            }
            self._update_session(session_id, progress=100, status='completed', current_phase='completed', result=result)
            self.metrics.record_task('research', duration, 'success')
            return result
        except Exception as e:
            logger.error(f"Research execution error: {e}\n{traceback.format_exc()}")
            self._update_session(session_id, status='error', error=str(e))
            return {'session_id': session_id, 'error': str(e), 'traceback': traceback.format_exc()}

    def _wait_for_tasks(self, task_ids: List[str], timeout: float = 300):
        start = time.time()
        while time.time() - start < timeout:
            all_done = all(
                task_id in self.orchestrator.completed_tasks or task_id in self.orchestrator.failed_tasks
                for task_id in task_ids
            )
            if all_done:
                return
            time.sleep(0.5)
        logger.warning(f"Task timeout: {[tid for tid in task_ids if tid not in self.orchestrator.completed_tasks]}")

    def _generate_comprehensive_report(self, query: str, sources: List[Dict], syntheses: List[Dict], critique: Dict, plan: Dict) -> str:
        sources_text = "\n\n".join([f"[{i+1}] {s.get('title', s.get('url', 'Source'))}\n{s.get('text', '')[:1500]}" for i, s in enumerate(sources[:200])])
        syntheses_text = "\n\n".join([f"Perspective: {s.get('metadata', {}).get('perspective', 'Unknown')}\n{s.get('synthesis', '')[:5000]}" for s in syntheses])
        critique_text = json.dumps(critique, indent=2)[:5000]
        plan_text = json.dumps(plan, indent=2)[:3000]
        report_prompt = f"""Generate a masterful, comprehensive research report (30-40 pages equivalent).

Query: {query}

Research Plan:
{plan_text}

Multi-perspective syntheses:
{syntheses_text}

Critical analysis:
{critique_text}

Key sources:
{sources_text}

Structure:
# EXECUTIVE SUMMARY (3 pages)
- Core findings
- Key implications
- Critical recommendations

# METHODOLOGY (2 pages)
- Research approach
- Sources ({len(sources)} total)
- AI models used
- Quality assurance

# COMPREHENSIVE FINDINGS (15-20 pages)
Multiple thematic sections with:
- Detailed analysis
- Supporting evidence
- Multiple perspectives
- Data and statistics
- Expert opinions
- Contradictions resolved

# CRITICAL ANALYSIS (4-5 pages)
- Strengths and limitations
- Uncertainty areas
- Confidence levels
- Alternative interpretations

# IMPLICATIONS (4-5 pages)
- Theoretical implications
- Practical applications
- Policy recommendations
- Business implications
- Future research

# FUTURE OUTLOOK (3-4 pages)
- Emerging trends
- Predictions
- Scenarios
- Long-term considerations

# CONCLUSION (2 pages)
- Summary
- Final synthesis
- Call to action

# REFERENCES
- Organized citations

Make it authoritative, nuanced, detailed, and actionable."""
        result, metadata = self.router.route_request(report_prompt, 'report', len(report_prompt), TaskPriority.HIGH, max_tokens=200000)
        enhancement_prompt = f"""Enhance this report with more depth, examples, and sophistication:

{result[:150000]}

Add:
- More specific examples
- Deeper analysis
- Additional perspectives
- Stronger evidence
- More nuanced conclusions
- Richer context

Return enhanced report."""
        enhanced, _ = self.router.route_request(enhancement_prompt, 'synthesis', len(enhancement_prompt), TaskPriority.MEDIUM, max_tokens=200000)
        return enhanced

    def _update_session(self, session_id: str, **kwargs):
        with self.session_lock:
            if session_id in self.sessions:
                self.sessions[session_id].update(kwargs)
                self.sessions[session_id]['last_update'] = time.time()

    def get_session(self, session_id: str) -> Dict:
        with self.session_lock:
            return self.sessions.get(session_id, {})

